import re

with open('/app/dataset/genealogy_trees.txt', 'r', encoding='utf-8') as f:
    lines = [line.rstrip('\n').ljust(10000) for line in f.readlines()]

# Extract people boxes
words = []
for r, line in enumerate(lines):
    for w in re.finditer(r'[A-ZĄĆĘŁŃÓŚŹŻ][a-ząćęłńóśźż]+', line):
        if w.group() not in ['FAMILY', 'TREE', 'GENERATOR']:
            words.append((r, w.start(), w.group()))

people = []
used = set()
for i, (r1, c1, w1) in enumerate(words):
    if i in used: continue
    found_last = False
    for j in range(i+1, len(words)):
        if j in used: continue
        r2, c2, w2 = words[j]
        if r1 == r2 and c1 < c2 and c2 - (c1 + len(w1)) < 3:
            people.append({
                'name': w1 + ' ' + w2, 'r1': r1, 'c1': c1, 'r2': r2, 'c2': c2 + len(w2)
            })
            used.add(i)
            used.add(j)
            found_last = True
            break
        elif r2 == r1 + 1 and abs(c1 - c2) < 5:
            people.append({
                'name': w1 + ' ' + w2, 'r1': r1, 'c1': min(c1, c2), 'r2': r2, 'c2': max(c1 + len(w1), c2 + len(w2))
            })
            used.add(i)
            used.add(j)
            found_last = True
            break
        if r2 > r1 + 1:
            break
    if not found_last:
        people.append({
            'name': w1, 'r1': r1, 'c1': c1, 'r2': r1, 'c2': c1 + len(w1)
        })

# Find the bounding box for each person
def find_box(person):
    # Search around the text for + - ~ | │
    r_min, r_max = person['r1'], person['r2']
    c_min, c_max = person['c1'], person['c2']

    # expand up to find top border
    top_r = r_min - 1
    while top_r >= 0 and not any(c in '+-~' for c in lines[top_r][c_min:c_max]):
        top_r -= 1
        if r_min - top_r > 3: break

    # expand down to find bottom border
    bottom_r = r_max + 1
    while bottom_r < len(lines) and not any(c in '+-~' for c in lines[bottom_r][c_min:c_max]):
        bottom_r += 1
        if bottom_r - r_max > 3: break

    person['box_top'] = top_r if top_r >= 0 and any(c in '+-~' for c in lines[top_r][c_min:c_max]) else r_min
    person['box_bottom'] = bottom_r if bottom_r < len(lines) and any(c in '+-~' for c in lines[bottom_r][c_min:c_max]) else r_max

for p in people:
    find_box(p)

def get_person_by_name(name):
    for p in people:
        if p['name'] == name:
            return p
    return None

def trace_horizontal(r, c_start):
    valid = set('-~+_.')
    children = []

    # go left
    c = c_start
    while c >= 0:
        if lines[r][c] in valid:
            if lines[r+1][c] in '|│+':
                children.append(c)
            c -= 1
        elif lines[r][c-1] in valid:
            c -= 1
        elif lines[r][c-2] in valid:
            c -= 2
        else:
            break

    # go right
    c = c_start + 1
    while c < 10000:
        if lines[r][c] in valid:
            if lines[r+1][c] in '|│+':
                children.append(c)
            c += 1
        elif lines[r][c+1] in valid:
            c += 1
        elif lines[r][c+2] in valid:
            c += 2
        else:
            break
    return list(set(children))

def get_children(person):
    bottom_r = person['box_bottom']
    children_names = []
    # find vertical lines going down from bottom_r
    for c in range(person['c1'] - 5, person['c2'] + 5):
        if c < 0 or c >= 10000: continue
        if lines[bottom_r+1][c] in '|│':
            # trace down
            curr_r = bottom_r + 1
            while curr_r < len(lines):
                if lines[curr_r][c] in '|│':
                    curr_r += 1
                elif lines[curr_r][c] in '-~+_':
                    # hit horizontal line
                    down_cols = trace_horizontal(curr_r, c)
                    for dc in down_cols:
                        # trace dc down to a person
                        dr = curr_r + 1
                        while dr < len(lines):
                            if lines[dr][dc] in '|│':
                                dr += 1
                            else:
                                # hit a box or empty space
                                # check if dr is top of some person's box
                                found = False
                                for p in people:
                                    if p['box_top'] == dr and p['c1'] - 10 <= dc <= p['c2'] + 10:
                                        children_names.append(p['name'])
                                        found = True
                                        break
                                if not found:
                                    # maybe dr is missing top border, and hits person name directly
                                    for p in people:
                                        if p['r1'] == dr and p['c1'] - 10 <= dc <= p['c2'] + 10:
                                            children_names.append(p['name'])
                                            found = True
                                            break
                                break
                    break
                else:
                    # check if we hit a box directly
                    for p in people:
                        if p['box_top'] == curr_r and p['c1'] - 10 <= c <= p['c2'] + 10:
                            children_names.append(p['name'])
                            break
                    break
    return list(set(children_names))

gg_grandpa = get_person_by_name('Przemysław Kurczab')
if not gg_grandpa:
    print("Could not find Przemysław Kurczab")
else:
    direct_children = get_children(gg_grandpa)
    print(f"Direct children of {gg_grandpa['name']}: {direct_children}")
    for child_name in direct_children:
        child = get_person_by_name(child_name)
        grandchildren = get_children(child)
        print(f"  {child_name} has {len(grandchildren)} children: {grandchildren}")
